# Knowledge Propagation Tracker - runnable demo (JAH-ATK196-000001)
from collections import deque, defaultdict
RANK = 1
SIG = False
REUSE = [('paper2', 'paper1', 'citation'), ('paper3', 'paper1', 'quote'), ('datasetB', 'paper2', 'derivation'), ('blog', 'paper3', 'paraphrase')]  # (reuser, source, kind)
children = defaultdict(list)
for reuser, src, kind in REUSE: children[src].append((reuser, kind))
SOURCE = REUSE[0][1]
seen, q, order = set(), deque([SOURCE]), []
while q:
    n = q.popleft()
    if n in seen: continue
    seen.add(n); order.append(n)
    q.extend(c for c, _ in children[n])
print("fact originated at:", SOURCE)
print("propagated to %d nodes:" % (len(order)-1))
for n in order[1:]:
    print("  ", n)
if RANK >= 2:
    depth = {}
    def dep(n, d=0):
        depth[n] = max(depth.get(n, 0), d)
        for c, _ in children[n]: dep(c, d+1)
    dep(SOURCE)
    print("max propagation depth:", max(depth.values()) if depth else 0)
if RANK >= 3:
    print("reuse edges:", len(REUSE))
if SIG:
    print("Signature lineage stamp: JAH-SIG-PRP-" + "JAH-ATK196-000001")
print("record:", "JAH-ATK196-000001", "OK")

